"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9532],{9532:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/0115da35c33abc8e7f7b804db3d7b5f1.jpg\\"\\n  title=\\"Ca De Vin\\"\\n  cuisine=\\"Italian\\"\\n  address=\\"Myer, 314-336, Bourke Street Mall, Greek Precinct, Melbourne, Victoria, 3000, Australia\\"\\n  rating=3\\n  tags=\\"restaurant\\"\\n/>\\n</center>\\n\\n## Ordered\\n```menu\\n{\\n\\"title\\": \\"Lasagna\\",\\n\\"rating\\": 3.5\\n}\\n---\\nOven-baked lasagna filled with house-made Bolognese, mozzarella, and Neapolitan sauce.\\n```\\n```menu\\n{\\n\\"title\\": \\"Eggplant Parmigiana\\",\\n\\"rating\\": 3.5\\n}\\n---\\nRoman-style pizza topped with grilled eggplant, mozzarella cheese, and fresh basil.\\n```\\n## Review\\nAn Italian restaurant located in <mark>Postal Lane</mark>, a storied alley next to the Melbourne GPO building.  \\n\\nSitting at an outdoor table in the laneway watching people pass by, we could soak in Melbourne\'s vibrant ```local atmosphere```.  \\n```adcard\\n```\\nThe dishes we ordered were the signature chef-recommended ```Lasagna``` and ```Eggplant Parmigiana```.  \\n\\nThe presentation was great and the food tasted good overall, but it wasn\'t distinctly memorable enough to leave a strong impression — it felt a little ordinary.  \\n\\nIf anything, what stood out most that day was the <mark>Hawkers Pilsner</mark>, a local Melbourne craft beer I tried for the first time.  \\n\\nIts clean, crisp finish cut right through the richness of the food, and I loved it.  \\nIt\'s a great spot to enjoy the vibes of a beautiful laneway and a cold local beer rather than the food itself.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/0115da35c33abc8e7f7b804db3d7b5f1.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Ca De Vin\\">\\n<img src=\\"/assets/snippets/location/ccb80eeecc4eb5b2d510c5ca38cf19ca.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Ca De Vin\\">\\n<img src=\\"/assets/snippets/location/1c6ea669923d1096f7e4b7cd7464946d.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Ca De Vin\\">\\n<img src=\\"/assets/snippets/location/39726e08ca5ef94cc5741997e0c3a5ac.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Ca De Vin\\">\\n</pictures>\\n"}')}}]);